<?php use Namira\{Db,Security,Protocol,StoreSettings}; ?>
<link rel="stylesheet" href="/assets/store.css?v=010"><h1>خریدهای من</h1><nav class="store-tabs"><?php foreach(['orders'=>'سفارش‌ها','quotes'=>'استعلام‌ها','downloads'=>'فایل‌های خریداری‌شده','messages'=>'اعلان‌ها','addresses'=>'نشانی‌ها'] as $k=>$label): ?><a class="pill <?= $section===$k?'active':'' ?>" href="<?= e(url('store-account',['section'=>$k])) ?>"><?= $label ?></a><?php endforeach ?><a class="pill" href="<?= e(url('account')) ?>">حساب نامیرا</a></nav>
<?php if($section==='orders'): ?><?php foreach($result['items'] as $o): ?><article class="panel"><a href="<?= e(url('store-order',['id'=>$o['id']])) ?>">سفارش #<?= fa($o['id']) ?></a><p><?= fa(number_format((int)$o['total'])) ?> تومان · <?= e($o['status'].' · '.$o['created_at']) ?></p></article><?php endforeach ?><?php if(!$result['items']): ?><p class="empty">هنوز سفارشی ندارید.</p><?php endif;view('public-pagination',['count'=>$result['count'],'per'=>$result['per'],'page'=>$result['page'],'route'=>'store-account','filters'=>[]]); ?>
<?php elseif($section==='quotes'):foreach(Db::query($db,'SELECT q.*,p.title FROM store_quotes q JOIN variants v ON v.id=q.variant_id JOIN products p ON p.id=v.product_id WHERE q.user_id=? ORDER BY q.id DESC',[$actor['id']])->fetchAll() as $q): ?><section class="panel"><h2><?= e($q['title']) ?></h2><p><?= e($q['status']) ?></p><?php if($q['order_id']): ?><a href="<?= e(url('store-order',['id'=>$q['order_id']])) ?>">مشاهده سفارش</a><?php elseif($q['status']==='offered'&&$q['expires_at']>time()): ?><p>قیمت هر واحد <?= fa(number_format((int)$q['amount'])) ?> تومان · اعتبار تا <?= e(date('Y-m-d H:i',$q['expires_at'])) ?></p><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="commerce-checkout"><input type="hidden" name="checkout_key" value="<?= e($_SESSION['checkout_key']??=bin2hex(random_bytes(32))) ?>"><input type="hidden" name="quote_id" value="<?= (int)$q['id'] ?>"><input type="hidden" name="accept_price_changes" value="1"><?php foreach(['customer'=>'نام گیرنده','phone'=>'موبایل','province'=>'استان (فیزیکی)','city'=>'شهر (فیزیکی)','postal_code'=>'کدپستی (فیزیکی)','address'=>'نشانی (فیزیکی)'] as $k=>$label): ?><label><?= $label ?><input name="<?= $k ?>" <?= in_array($k,['customer','phone'],true)?'required':'' ?>></label><?php endforeach ?><label>روش ارسال<select name="shipping_method"><option value="">فقط دیجیتال</option><?php foreach(StoreSettings::get($db)['shipping'] as $s): ?><option value="<?= e($s['id']) ?>"><?= e($s['title']) ?></option><?php endforeach ?></select></label><button class="primary">پذیرش مبلغ و ایجاد سفارش پرداخت</button></form><?php endif ?></section><?php endforeach ?>
<?php elseif($section==='downloads'):foreach(Db::query($db,"SELECT i.*,d.snapshot,d.digital_state FROM order_items i JOIN store_item_details d ON d.item_id=i.id JOIN store_order_details o ON o.order_id=i.order_id JOIN payments p ON p.order_id=i.order_id WHERE o.user_id=? AND p.status='verified' AND d.digital_state IN('available','downloaded') AND d.status NOT IN('cancelled','returned')",[$actor['id']])->fetchAll() as $i): ?><article class="panel"><h2><?= e($i['title']) ?></h2><a class="outline" href="<?= e(url('store-order',['id'=>$i['order_id']])) ?>">جزئیات سفارش و فایل‌ها</a></article><?php endforeach ?>
<?php elseif($section==='messages'):foreach(Db::query($db,'SELECT * FROM store_notifications WHERE user_id=? ORDER BY id DESC LIMIT 100',[$actor['id']])->fetchAll() as $n): ?><article class="panel"><p><?= e($n['message']) ?></p><small><?= e($n['created_at']) ?></small><a href="<?= e(url('store-order',['id'=>$n['order_id']])) ?>">مشاهده سفارش</a></article><?php endforeach ?>
<?php elseif($section==='addresses'):$addresses=Db::query($db,'SELECT * FROM account_addresses WHERE user_id=?',[$actor['id']])->fetchAll();$addresses[]=['id'=>0];foreach($addresses as $a): ?><section class="panel"><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="commerce-address"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><h2><?= $a['id']?'ویرایش نشانی':'نشانی جدید' ?></h2><div class="fields"><?php foreach(['title'=>'عنوان','recipient'=>'گیرنده','phone'=>'موبایل','postal_code'=>'کدپستی','address'=>'نشانی کامل'] as $k=>$label): ?><label><?= $label ?><input name="<?= $k ?>" required value="<?= e($a[$k]??'') ?>"></label><?php endforeach ?></div><button class="primary">ذخیره نشانی</button></form></section><?php endforeach;endif ?>
